   * Обычно устанавливается автоматически при достижении последней страницы.
   */
  hasMore?: boolean;
}

/**
 * Состояние хука useInfiniteScroll.
 */
export interface UseInfiniteScrollState<T> {
  /** Все накопленные элементы со всех загруженных страниц */
  items: T[];
  /** Текущая страница, которая была запрошена или находится в процессе загрузки */
