    /**
     * Максимальная ёмкость ведра (максимальное количество токенов, которое может быть накоплено).
     */
    private final int capacity;

    /**
     * Скорость пополнения ведра (токенов в секунду).
     */
    private final double refillRate;

    /**
     * Текущее количество токенов в ведре.
     * Используется тип double, чтобы корректно обрабатывать дробные значения при расчёте пополнения.
     */
    private double tokens;

    /**
     * Время последнего обновления количества токенов (в миллисекундах, системное время).
     */
