     * @param refillRate скорость пополнения ведра (токенов в секунду)
     * @throws IllegalArgumentException если capacity <= 0 или refillRate <= 0
     */
    public TokenBucketRateLimiter(int capacity, double refillRate) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Ёмкость ведра должна быть положительным числом");
        }
        if (refillRate <= 0) {
            throw new IllegalArgumentException("Скорость пополнения должна быть положительным числом");
        }
        this.capacity = capacity;
        this.refillRate = refillRate;
        // Изначально ведро заполнено полностью
