 * Ищет активного пользователя по логину.
 *
 * @param login Логин пользователя, который нужно найти (регистр не учитывается).
 * @return Опциональный объект с найденным пользователем, если он существует и активен;
 *         иначе Optional.empty().
 */
public Optional<User> findActive(String login) {
    // Получаем поток из коллекции пользователей
    return users.stream()
        // Фильтруем пользователей, у которых логин совпадает с переданным (без учета регистра)
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Оставляем только тех пользователей, которые:
        // 1. Не заблокированы (!u.isBlocked())
        // 2. Имеют срок действия, который еще не истек (u.getExpiresAt().isAfter(Instant.now()))
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Возвращаем первого найденного пользователя, соответствующего условиям фильтрации
        .findFirst();
}
