/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия (целое число).</returns>
/// <exception cref="InvalidOperationException">
/// Бросается, если все попытки исчерпаны и ошибка не была обработана.
/// </exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения нескольких попыток
    for (var i = 0; i < attempts; i++)
    {
        try 
        {
            // Пытаемся выполнить переданное асинхронное действие
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
