// Функция worker представляет собой обработчик задач (воркер).
// Она читает задачи из канала jobs, обрабатывает их и отправляет результаты в канал results.
// Параметр wg используется для синхронизации завершения всех воркеров.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Деферированный вызов wg.Done() гарантирует, что счетчик WaitGroup будет уменьшен
    // при выходе из функции, независимо от того, как именно она завершилась.
    defer wg.Done()

    // Цикл range по каналу jobs блокируется до получения новой задачи или закрытия канала.
    // Это позволяет воркеру работать непрерывно, пока есть задачи в очереди.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Возвращаются результат r и возможная ошибка err.
        r, err := process(j)

        // Если при обработке возникла ошибка:
        if err != nil {
            // Логируем ошибку с идентификатором задачи для отслеживания проблем.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей, не отправляя результат.
            continue
        }

        // Если обработка прошла успешно, отправляем результат r в канал results.
        // Операция блокируется, пока потребитель не заберет значение из канала.
        results <- r
    }
}
