/**
 * Создаёт функцию-обёртку, которая откладывает вызов переданной функции `fn`
 * на указанное количество миллисекунд `ms`.
 * Если функция вызывается повторно до истечения таймера, предыдущий таймер
 * сбрасывается и устанавливается новый. Это позволяет вызывать функцию только
 * один раз после того, как последовательность вызовов прекратится.
 *
 * @param fn - Функция, которую нужно "задебаунсить".
 * @param ms - Задержка в миллисекундах.
 * @returns Обёрнутая функция с теми же параметрами, что и исходная.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора текущего таймера.
  // Изначально она не определена (undefined), так как таймер ещё не создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и оригинальная `fn`.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (t !== undefined), очищаем его.
    // Это предотвращает выполнение предыдущего запланированного вызова.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер, который вызовет оригинальную функцию `fn`
    // через `ms` миллисекунд с переданными аргументами `args`.
    // Сохраняем идентификатор нового таймера в переменную `t`, чтобы иметь возможность
    // отменить его при следующем вызове.
    t = setTimeout(() => fn(...args), ms);
  };
}
