///
/// # Аргументы
/// * `s` - входная строка, содержащая пары ключ-значение, разделенные точкой с запятой.
///
/// # Возвращаемое значение
/// HashMap, где ключи — это нижний регистр и обрезанные пробелами ключи,
/// а значения — обрезанные пробелами значения.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Разбиваем исходную строку по символу ';' на отдельные пары "ключ=значение"
    s.split(';')
        // Для каждой части пытаемся разделить её по первому вхождению '='.
        // Если '=' не найден (например, пустая строка или просто текст без '='),
        // метод split_once вернёт None, и filter_map отфильтрует такой элемент.
        .filter_map(|p| p.split_once('='))
        // Теперь у нас есть кортежи (ключ, значение).
        // Обрезаем лишние пробелы с обеих сторон ключа и переводим его в нижний регистр.
        // Значение также обрезаем от лишних пробелов, но оставляем как есть (без изменения регистра).
